def route_group_allowed(path: str, access: dict) -> dict:
    actor = access.get('actor') if isinstance(access.get('actor'), dict) else {}
    role = str(actor.get('role') or '').strip().lower()
    scopes = {str(scope).strip().lower() for scope in actor.get('scopes', []) if str(scope).strip()}
    privileged = {'admin', 'super_admin', 'ops_manager'}
    ops_roles = {'operator', 'ops', 'ops_manager', 'support_reviewer', 'trust_reviewer'}
    finance_roles = {'accountant', 'finance_ops', 'finance_manager', 'payment_ops'}
    connector_roles = {'connector_admin', 'ops', 'ops_manager'}

    def allow(roles: set[str], scope_prefixes: tuple[str, ...]=()) -> bool:
        if role in privileged:
            return True
        if role not in roles:
            return False
        if not scope_prefixes:
            return True
        return any((scope.startswith(prefix) for scope in scopes for prefix in scope_prefixes))
    if path.startswith(('/api/core/identity/workspace-access/', '/api/core/identity/workspace-memberships', '/api/core/identity/workspace-invites')):
        return {'ok': allow({'connector_admin', 'ops_manager'}, ('identity.', 'connect.', 'ops.')), 'reason': 'workspace_access_scope_required'}
    if path.startswith(('/api/core/identity/credentials', '/api/core/identity/session/issue', '/api/core/identity/session/revoke', '/api/core/identity/api-keys')):
        ok = role in privileged or 'identity.admin' in scopes
        return {'ok': ok, 'reason': 'identity_admin_scope_required'}
    if public_theme_admin_route_requires_auth(path):
        return {'ok': allow(privileged | {'ops', 'ops_manager', 'connector_admin'}, ('ops.theme', 'identity.admin')), 'reason': 'theme_admin_scope_required'}
    if path.startswith(('/api/core/ops/liveuintest-rollout-status', '/ops/liveuintest-review', '/ops/liveuin-test-review', '/ops-liveuintest-review.html')):
        return {'ok': allow(ops_roles | finance_roles), 'reason': 'ops_liveuintest_review_role_required'}
